-- c016-v011: no alguno pues a–él menosprecie enviad–adelante pero a–él en paz para–que venga a mí espero pues a–él con los hermanos
-- c016-v012: Acerca–de pero Apollōs el hermano mucho rogué a–él para–que fuese a vosotros con los hermanos y de–ninguna–manera no era voluntad que ahora fuese vendrá pero cuando tenga–oportunidad
-- c016-v013: Velad estad–firmes en la fe sed–varones fortaleceos
-- c016-v014: todas–cosas vuestras en amor háganse
-- c016-v015: Exhorto pero a–vosotros hermanos sabéis la casa de–Stephanâs que es primicias de–la Achaía y para ministerio a–los santos se–dedicaron a–sí–mismos
-- c016-v016: para–que también vosotros os–sujetéis a–los tales y a–todo el–que colabora y trabaja
-- c016-v017: me–gozo pero por la venida de–Stephanâs y de–Phortounátos y de–Achaïkós porque la vuestra falta estos suplieron
