-- c016-v019: Saludan a–vosotros las iglesias de–la Asia saluda a–vosotros en Señor mucho Akýlas y Príska con la en casa de–ellos iglesia
-- c016-v020: saludan a–vosotros los hermanos todos Saludad unos–a–otros con beso santo
